mapper.select:
SELECT COUNT(*)
FROM user_rating
WHERE receiver_user_id = #{receiverUserId}
    AND evaluator_user_id = #{evaluatorUserId}
    AND match_id = #{matchId}
    AND match_type = #{matchType}

mapper.update:
UPDATE user_rating
SET
    score = #{score},
    created_at = NOW()
WHERE receiver_user_id = #{receiverUserId}
    AND evaluator_user_id = #{evaluatorUserId}
    AND match_id = #{matchId}
    AND match_type = #{matchType}
